-- no-transaction
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS idx_users_google_id_unique ON users(google_id) WHERE google_id IS NOT NULL;
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS idx_users_linkedin_id_unique ON users(linkedin_id) WHERE linkedin_id IS NOT NULL;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_users_search_document ON users USING GIN(search_document);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_users_name_trgm ON users USING GIN(lower(full_name) gin_trgm_ops);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_projects_public_order ON projects(user_id, status, is_featured DESC, sort_order, created_at DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_projects_search_document ON projects USING GIN(search_document);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_projects_technologies_gin ON projects USING GIN(technologies);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_blocks_project_sort ON blocks(project_id, sort_order, id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_media_user_created ON media(user_id, created_at DESC, id DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_media_project ON media(project_id) WHERE project_id IS NOT NULL;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_collaborators_user_status ON project_collaborators(user_id, status, project_id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_collaborators_project_status ON project_collaborators(project_id, status, user_id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_team_members_user_status ON team_members(user_id, status, team_id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_team_members_team_status ON team_members(team_id, status, joined_at);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_team_projects_project ON team_projects(project_id, team_id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_teams_owner ON teams(owner_id, created_at DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_secure_tokens_lookup ON secure_token_registry(entity_type, token_hash);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_invitations_state ON invitations(status, expires_at) WHERE status = 'pending';
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_endorsements_owner_status ON endorsements(to_user_id, is_approved, approved_at DESC, created_at DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_endorsements_project ON endorsements(project_id) WHERE project_id IS NOT NULL;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_notifications_user_created ON notifications(user_id, created_at DESC, id DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_notifications_unread_partial ON notifications(user_id, created_at DESC) WHERE is_read = false;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_posts_search_document ON discover_posts USING GIN(search_document);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_posts_user_created ON discover_posts(user_id, created_at DESC, id DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_comments_post_created ON post_comments(post_id, created_at, id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_post_likes_user_post ON post_likes(user_id, post_id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_post_likes_created ON post_likes(created_at, post_id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_follows_following_created ON user_follows(following_id, created_at DESC, follower_id);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_ai_changes_thread_created ON ai_change_sets(thread_id, created_at DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_ai_changes_user_status ON ai_change_sets(user_id, status, applied_at DESC, created_at DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_jobs_user_created ON background_jobs(user_id, created_at DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_jobs_status_created ON background_jobs(status, created_at) WHERE status IN ('queued', 'active');
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_refresh_tokens_user_active ON auth_refresh_tokens(user_id, expires_at) WHERE revoked_at IS NULL;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_revisions_user_created ON portfolio_revisions(user_id, created_at DESC);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_analytics_daily_subject_day ON analytics_daily(subject_type, subject_id, day);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_analytics_daily_visitors_subject_day ON analytics_daily_visitors(subject_type, subject_id, day, visitor_hash);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_integration_requests_user_created ON integration_requests(user_id, created_at DESC);
